pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 d, uint256 w, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(actor.code.length == 0);
        vm.assume(d > 0);
        vm.assume(w >= d);
        vm.deal(actor, d);
        vm.prank(actor);
        c.deposit{value: d}();
        vm.prank(actor);
        c.withdraw(d);
        // account emptied: any further withdrawal must revert on the reference
        vm.prank(actor);
        bool ok2;
        try c.withdraw(1) { ok2 = true; } catch { ok2 = false; }
        assertTrue(!ok2);
    }
}
